  const [lang, setLangState] = useState<Lang>(getConfig().lang as Lang);

  useEffect(() => {
    return subscribeConfigure((config) => {
      setLangState(config.lang as Lang);
    });
  }, []);

  const setLang = useCallback((newLang: Lang) => {
    configure({lang: newLang});
